26	function snapshot() {
27	  return {
28	    enabled: !!(state && state.settings.smartReviewEnabled),
29	    monitoring,
30	    stress,
31	    stressText: Number.isFinite(stress) ? `${Math.round(stress)}` : '--',
32	    motionText: accelSamples.length >= contextEngine.MIN_ACCEL_SAMPLES
33	      ? (contextEngine.isStationary(accelSamples) ? '静止' : '活动')
34	      : '等待数据',
35	    decision,
36	    ready,
37	    stressMax: state ? state.settings.stressMax : contextEngine.DEFAULT_STRESS_MAX,
38	    acceptanceRate: state ? Number(state.context.acceptanceRate || 0) : 0,
39	  };
40	}
41	
42	function emit() {
43	  const value = snapshot();
44	  listeners.slice().forEach((listener) => {
45	    try { listener(value); } catch (error) {}
46	  });
47	}
48	
49	async function evaluate() {
50	  if (evaluating || !state) return;
51	  evaluating = true;
52	  try {
53	    const result = contextEngine.evaluateReviewWindow({
54	      settings: state.settings,
55	      plan: state.plan,
56	      stress,
57	      accelSamples,
58	      lastRecommendationAt: state.context.lastRecommendationAt,
59	      now: Date.now(),
60	    });
61	    if (result.reason === 'cooldown' && state.context.lastReason === 'ready') {
62	      ready = true;
63	      decision = '本轮推荐已经送达';
64	      emit();
65	      return;
66	    }
67	    ready = result.ready;
68	    decision = contextEngine.reasonLabel(result.reason);
69	    if (result.ready && state.context.lastReason !== 'ready') {
70	      state.context.lastReason = 'ready';
71	      state.context.lastRecommendationAt = Date.now();
72	      state.context.shown = Number(state.context.shown || 0) + 1;
73	      await store.save(state);
74	      safeVibrate();
75	    } else if (!result.ready && state.context.lastReason !== result.reason) {
76	      state.context.lastReason = result.reason;
77	      await store.save(state);
78	    }
79	    emit();
80	  } finally {
81	    evaluating = false;
82	  }
83	}
