85	function applyStress(value) {
86	  const number = Number(value);
87	  if (!Number.isFinite(number)) return;
88	  stress = number;
89	  evaluate();
90	}
91	
92	function applyMotion(sample) {
93	  accelSamples = accelSamples.concat([sample]).slice(-12);
94	  evaluate();
95	  emit();
96	}
97	
98	function readRecentStress() {
99	  try {
100	    const request = health.getRecentSamples({ dataTypes: [health.DATA_TYPES.STRESS] });
101	    if (request && typeof request.then === 'function') {
102	      request.then((items) => {
103	        const match = (items || []).find((item) => item.dataType === health.DATA_TYPES.STRESS);
104	        if (match && match.data) applyStress(match.data.value);
105	      }).catch(() => {});
106	    }
107	  } catch (error) {}
108	}
