110	async function start() {
111	  state = await store.load();
112	  if (!state.settings.smartReviewEnabled || monitoring) {
113	    decision = state.settings.smartReviewEnabled ? decision : '智能推荐未开启';
114	    emit();
115	    return snapshot();
116	  }
117	  monitoring = true;
118	  decision = '正在读取设备状态';
119	  readRecentStress();
120	  try {
121	    health.subscribeSample({
122	      dataType: health.DATA_TYPES.STRESS,
123	      callback: (sample) => applyStress(sample && sample.value),
124	      fail: () => {
125	        stress = null;
126	        decision = '当前设备不支持压力数据';
127	        emit();
128	      },
129	    });
130	  } catch (error) {
131	    decision = '当前设备不支持压力数据';
132	  }
133	  try {
134	    sensor.subscribeAccelerometer({
135	      callback: applyMotion,
136	      fail: () => {
137	        accelSamples = [];
138	        decision = '当前设备不支持活动数据';
139	        emit();
140	      },
141	    });
142	  } catch (error) {
143	    decision = '当前设备不支持活动数据';
144	  }
145	  emit();
146	  return snapshot();
147	}
148	
149	function stop() {
150	  if (monitoring) {
151	    try { health.unsubscribeSample({ dataType: health.DATA_TYPES.STRESS }); } catch (error) {}
152	    try { sensor.unsubscribeAccelerometer(); } catch (error) {}
153	  }
154	  monitoring = false;
155	  stress = null;
156	  accelSamples = [];
157	  ready = false;
158	  emit();
159	}
