161	async function setEnabled(enabled) {
162	  state = await store.load();
163	  state.settings.smartReviewEnabled = !!enabled;
164	  if (!enabled) {
165	    state.context.lastReason = 'disabled';
166	    decision = '智能推荐未开启';
167	  }
168	  await store.save(state);
169	  if (enabled) return start();
170	  stop();
171	  return snapshot();
172	}
173	
174	async function recordFeedback(accepted) {
175	  state = await store.load();
176	  state = contextEngine.recordRecommendationFeedback(state, !!accepted, stress, Date.now());
177	  await store.save(state);
178	  ready = false;
179	  decision = contextEngine.reasonLabel(state.context.lastReason);
180	  emit();
181	  return snapshot();
182	}
183	
184	function subscribe(listener) {
185	  if (typeof listener !== 'function') return function () {};
186	  listeners.push(listener);
187	  listener(snapshot());
188	  return function () {
189	    const index = listeners.indexOf(listener);
190	    if (index >= 0) listeners.splice(index, 1);
191	  };
192	}
193	
194	module.exports = { start, stop, setEnabled, recordFeedback, subscribe, snapshot };
