1	const DEFAULT_STRESS_MAX = 25;
2	const MIN_ACCEL_SAMPLES = 6;
3	const STATIONARY_DELTA_MAX = 0.35;
4	const DUE_LOOKAHEAD_MS = 30 * 60 * 1000;
5	const RECOMMENDATION_COOLDOWN_MS = 30 * 60 * 1000;
6	const MIN_STRESS_MAX = 15;
7	const MAX_STRESS_MAX = 35;
8	
9	function finiteNumber(value, fallback) {
10	  const number = Number(value);
11	  return Number.isFinite(number) ? number : fallback;
12	}
13	
14	function clamp(value, min, max) {
15	  return Math.min(max, Math.max(min, value));
16	}
17	
18	function isStationary(samples) {
19	  const points = (samples || []).slice(-12).filter((sample) => sample
20	    && Number.isFinite(Number(sample.x))
21	    && Number.isFinite(Number(sample.y))
22	    && Number.isFinite(Number(sample.z)));
23	  if (points.length < MIN_ACCEL_SAMPLES) return false;
24	
25	  let movement = 0;
26	  for (let i = 1; i < points.length; i++) {
27	    const dx = Number(points[i].x) - Number(points[i - 1].x);
28	    const dy = Number(points[i].y) - Number(points[i - 1].y);
29	    const dz = Number(points[i].z) - Number(points[i - 1].z);
30	    movement += Math.sqrt(dx * dx + dy * dy + dz * dz);
31	  }
32	  return movement / (points.length - 1) <= STATIONARY_DELTA_MAX;
33	}
34	
35	function evaluateReviewWindow(input) {
36	  const settings = (input && input.settings) || {};
37	  if (!settings.smartReviewEnabled) return { ready: false, reason: 'disabled' };
38	
39	  const plan = input && input.plan;
40	  if (!plan || Number(plan.sessionsCompleted || 0) <= 0) {
41	    return { ready: false, reason: 'no_review' };
42	  }
43	
44	  const stress = finiteNumber(input && input.stress, NaN);
45	  if (!Number.isFinite(stress)) return { ready: false, reason: 'waiting_health' };
46	  if (stress > finiteNumber(settings.stressMax, DEFAULT_STRESS_MAX)) {
47	    return { ready: false, reason: 'high_stress' };
48	  }
49	  if (!isStationary(input && input.accelSamples)) {
50	    return { ready: false, reason: 'moving' };
51	  }
52	
53	  const now = finiteNumber(input && input.now, Date.now());
54	  const dueAt = finiteNumber(plan.nextDueAt, now);
55	  if (dueAt > now + DUE_LOOKAHEAD_MS) return { ready: false, reason: 'not_due' };
56	
57	  const last = finiteNumber(input && input.lastRecommendationAt, 0);
58	  if (last > 0 && now - last < RECOMMENDATION_COOLDOWN_MS) {
59	    return { ready: false, reason: 'cooldown' };
60	  }
61	
62	  return {
63	    ready: true,
64	    reason: 'ready',
65	    stress,
66	    dueAt,
67	  };
68	}
69	
70	function reasonLabel(reason) {
71	  const labels = {
72	    disabled: '智能推荐未开启',
73	    no_review: '完成首次学习后开始判断',
74	    waiting_health: '正在读取压力数据',
75	    high_stress: '当前压力较高，暂不打扰',
76	    moving: '检测到活动，等待安静时刻',
77	    not_due: '还未进入复习窗口',
78	    cooldown: '本轮推荐已经送达',
79	    ready: '当前状态适合短时复习',
80	    accepted: '已接受，本次反馈会优化后续时机',
81	    dismissed: '已稍后处理，后续会减少打扰',
82	  };
83	  return labels[reason] || '正在判断复习窗口';
84	}
85	
86	function recordRecommendationFeedback(state, accepted, stress, now) {
87	  const input = state || {};
88	  const settings = Object.assign({ stressMax: DEFAULT_STRESS_MAX }, input.settings || {});
89	  const context = Object.assign({
90	    lastRecommendationAt: 0,
91	    lastReason: '',
92	    shown: 0,
93	    accepted: 0,
94	    dismissed: 0,
95	  }, input.context || {});
96	  const sample = finiteNumber(stress, settings.stressMax);
97	  const target = accepted
98	    ? Math.max(settings.stressMax, sample + 2)
99	    : Math.min(settings.stressMax, sample - 2);
100	  settings.stressMax = Math.round(clamp(
101	    settings.stressMax * 0.8 + target * 0.2,
102	    MIN_STRESS_MAX,
103	    MAX_STRESS_MAX,
104	  ));
105	  if (accepted) context.accepted += 1;
106	  else context.dismissed += 1;
107	  context.lastReason = accepted ? 'accepted' : 'dismissed';
108	  context.lastRecommendationAt = finiteNumber(now, Date.now());
109	  const total = context.accepted + context.dismissed;
110	  context.acceptanceRate = total > 0 ? Math.round(context.accepted * 100 / total) : 0;
111	  return Object.assign({}, input, { settings, context });
112	}
113	
