115	  DEFAULT_STRESS_MAX,
116	  MIN_ACCEL_SAMPLES,
117	  DUE_LOOKAHEAD_MS,
118	  RECOMMENDATION_COOLDOWN_MS,
119	  MIN_STRESS_MAX,
120	  MAX_STRESS_MAX,
121	  isStationary,
122	  evaluateReviewWindow,
123	  reasonLabel,
124	  recordRecommendationFeedback,
125	};
