4	const ASK_TIMEOUT_MS = 25000;
5	
6	function ask(query, timeoutMs) {
7	  return new Promise((resolve, reject) => {
8	    let settled = false;
9	    const timer = setTimeout(() => {
10	      if (settled) return;
11	      settled = true;
12	      reject(new Error('AI service timed out'));
13	    }, timeoutMs || ASK_TIMEOUT_MS);
14	
15	    function finish(callback, value) {
16	      if (settled) return;
17	      settled = true;
18	      clearTimeout(timer);
19	      callback(value);
20	    }
21	
22	    let request;
23	    try {
24	      request = velaclaw.ask({
25	        query,
26	        success: function (result) { finish(resolve, (result && result.reply) || ''); },
27	        fail: function (message, code) {
28	          finish(reject, new Error(`${code}: ${message || 'AI service unavailable'}`));
29	        },
30	        complete: function () {},
31	      });
32	    } catch (error) {
33	      finish(reject, error);
34	      return;
35	    }
36	
37	    if (request && typeof request.then === 'function') {
38	      request.then(
39	        function (result) { finish(resolve, (result && result.reply) || ''); },
40	        function (error) {
41	          const reason = error instanceof Error ? error : new Error(String(error || 'AI service unavailable'));
42	          finish(reject, reason);
43	        },
44	      );
45	    }
46	  });
47	}
