49	async function createPlan(topic, minutes) {
50	  const now = Date.now();
51	  try {
52	    const reply = await ask(protocol.planPrompt(topic, minutes, now));
53	    return protocol.normalizePlan(protocol.extractPayload(reply), topic, minutes, now);
54	  } catch (error) {
55	    console.log('FocusLoop agent fallback:', error);
56	    return protocol.fallbackPlan(topic, minutes, now);
57	  }
58	}
