60	async function importPlan(minutes) {
61	  const now = Date.now();
62	  const reply = await ask(protocol.importPrompt(minutes), 60000);
63	  const payload = protocol.extractPayload(reply);
64	  return protocol.normalizePlan(payload, payload.topic || '导入材料', minutes, now, 'document');
65	}
