22	  let depth = 0;
23	  let inString = false;
24	  let escaped = false;
25	  for (let i = start; i < text.length; i++) {
26	    const ch = text[i];
27	    if (inString) {
28	      if (escaped) escaped = false;
29	      else if (ch === '\\') escaped = true;
30	      else if (ch === '"') inString = false;
31	      continue;
32	    }
33	    if (ch === '"') inString = true;
34	    else if (ch === '{') depth++;
35	    else if (ch === '}') {
