  const resolvedAgentPath = path.resolve(__dirname, '../src/common/agent.js');
  const resolvedVelaclawPath = path.resolve(__dirname, '../node_modules/@system/velaclaw.js');
  require.cache[resolvedVelaclawPath] = {
    id: resolvedVelaclawPath,
    filename: resolvedVelaclawPath,
    loaded: true,
    exports: { default: { ask() { return { then() {} }; } } },
  };
  const agent = require(resolvedAgentPath);
  const plan = await agent.importPlan(20);
  assert.strictEqual(plan.source, 'document');
