1	import health from '@service.health';
2	import sensor from '@system.sensor';
3	import vibrator from '@system.vibrator';
4	import store from './store.js';
5	import contextEngine from './context.js';
6	
7	let monitoring = false;
8	let evaluating = false;
9	let state = null;
10	let stress = null;
11	let accelSamples = [];
12	let decision = '智能推荐未开启';
13	let ready = false;
14	const listeners = [];
15	
16	function safeVibrate() {
17	  try {
18	    if (vibrator && typeof vibrator.vibrate === 'function') {
19	      vibrator.vibrate({ mode: 'short', complete() {} });
20	    }
21	  } catch (error) {
22	    console.log('FocusLoop context vibration unavailable:', error);
23	  }
24	}
25	
26	function snapshot() {
27	  return {
28	    enabled: !!(state && state.settings.smartReviewEnabled),
29	    monitoring,
30	    stress,
31	    stressText: Number.isFinite(stress) ? `${Math.round(stress)}` : '--',
32	    motionText: accelSamples.length >= contextEngine.MIN_ACCEL_SAMPLES
33	      ? (contextEngine.isStationary(accelSamples) ? '静止' : '活动')
34	      : '等待数据',
35	    decision,
36	    ready,
37	    stressMax: state ? state.settings.stressMax : contextEngine.DEFAULT_STRESS_MAX,
38	    acceptanceRate: state ? Number(state.context.acceptanceRate || 0) : 0,
39	  };
40	}
41	
42	function emit() {
43	  const value = snapshot();
44	  listeners.slice().forEach((listener) => {
45	    try { listener(value); } catch (error) {}
46	  });
47	}
48	
49	async function evaluate() {
50	  if (evaluating || !state) return;
51	  evaluating = true;
52	  try {
53	    const result = contextEngine.evaluateReviewWindow({
54	      settings: state.settings,
55	      plan: state.plan,
56	      stress,
57	      accelSamples,
58	      lastRecommendationAt: state.context.lastRecommendationAt,
59	      now: Date.now(),
60	    });
61	    if (result.reason === 'cooldown') {
62	      const gates = contextEngine.evaluateReviewWindow({
63	        settings: state.settings,
64	        plan: state.plan,
65	        stress,
66	        accelSamples,
67	        lastRecommendationAt: 0,
68	        now: Date.now(),
69	      });
70	      if (state.context.lastReason === 'ready' && gates.ready) {
71	        ready = true;
72	        decision = '本轮推荐已经送达';
73	        emit();
74	        return;
75	      }
76	      ready = false;
77	      decision = contextEngine.reasonLabel(gates.ready ? 'cooldown' : gates.reason);
78	      emit();
79	      return;
80	    }
81	    ready = result.ready;
82	    decision = contextEngine.reasonLabel(result.reason);
83	    if (result.ready && state.context.lastReason !== 'ready') {
84	      state.context.lastReason = 'ready';
85	      state.context.lastRecommendationAt = Date.now();
86	      state.context.shown = Number(state.context.shown || 0) + 1;
87	      await store.save(state);
88	      safeVibrate();
89	    } else if (!result.ready && state.context.lastReason !== result.reason) {
90	      state.context.lastReason = result.reason;
91	      await store.save(state);
92	    }
93	    emit();
94	  } finally {
95	    evaluating = false;
96	  }
97	}
98	
99	function applyStress(value) {
100	  const number = Number(value);
101	  if (!Number.isFinite(number)) return;
102	  stress = number;
103	  evaluate();
104	}
105	
106	function applyMotion(sample) {
107	  accelSamples = accelSamples.concat([sample]).slice(-12);
108	  evaluate();
109	  emit();
110	}
111	
112	function readRecentStress() {
113	  try {
114	    const request = health.getRecentSamples({ dataTypes: [health.DATA_TYPES.STRESS] });
115	    if (request && typeof request.then === 'function') {
116	      request.then((items) => {
117	        const match = (items || []).find((item) => item.dataType === health.DATA_TYPES.STRESS);
118	        if (match && match.data) applyStress(match.data.value);
119	      }).catch(() => {});
120	    }
121	  } catch (error) {}
122	}
123	
124	async function start() {
125	  state = await store.load();
126	  if (!state.settings.smartReviewEnabled || monitoring) {
127	    decision = state.settings.smartReviewEnabled ? decision : '智能推荐未开启';
128	    emit();
129	    return snapshot();
130	  }
131	  monitoring = true;
132	  decision = '正在读取设备状态';
133	  readRecentStress();
134	  try {
135	    health.subscribeSample({
136	      dataType: health.DATA_TYPES.STRESS,
137	      callback: (sample) => applyStress(sample && sample.value),
138	      fail: () => {
139	        stress = null;
140	        decision = '当前设备不支持压力数据';
141	        emit();
142	      },
143	    });
144	  } catch (error) {
145	    decision = '当前设备不支持压力数据';
146	  }
147	  try {
148	    sensor.subscribeAccelerometer({
149	      callback: applyMotion,
150	      fail: () => {
151	        accelSamples = [];
152	        decision = '当前设备不支持活动数据';
153	        emit();
154	      },
155	    });
156	  } catch (error) {
157	    decision = '当前设备不支持活动数据';
158	  }
159	  emit();
160	  return snapshot();
161	}
162	
163	function stop() {
164	  if (monitoring) {
165	    try { health.unsubscribeSample({ dataType: health.DATA_TYPES.STRESS }); } catch (error) {}
166	    try { sensor.unsubscribeAccelerometer(); } catch (error) {}
167	  }
168	  monitoring = false;
169	  stress = null;
170	  accelSamples = [];
171	  ready = false;
172	  emit();
173	}
174	
175	async function setEnabled(enabled) {
176	  state = await store.load();
177	  state.settings.smartReviewEnabled = !!enabled;
178	  if (!enabled) {
179	    state.context.lastReason = 'disabled';
180	    decision = '智能推荐未开启';
181	  }
182	  await store.save(state);
183	  if (enabled) return start();
184	  stop();
185	  return snapshot();
186	}
187	
188	async function recordFeedback(accepted) {
189	  state = await store.load();
190	  state = contextEngine.recordRecommendationFeedback(state, !!accepted, stress, Date.now());
191	  await store.save(state);
192	  ready = false;
193	  decision = contextEngine.reasonLabel(state.context.lastReason);
194	  emit();
195	  return snapshot();
196	}
197	
198	function subscribe(listener) {
199	  if (typeof listener !== 'function') return function () {};
200	  listeners.push(listener);
201	  listener(snapshot());
202	  return function () {
203	    const index = listeners.indexOf(listener);
204	    if (index >= 0) listeners.splice(index, 1);
205	  };
206	}
207	
208	module.exports = { start, stop, setEnabled, recordFeedback, subscribe, snapshot };
